def main(parsed_data) -> dict:
    def get_dict_list(field_name):
        if not isinstance(parsed_data, dict):
            return []

        value = parsed_data.get(field_name, [])
        if not isinstance(value, list):
            return []

        if not all(isinstance(item, dict) for item in value):
            return []

        return value

    return {
        "line_data": get_dict_list("地铁线路基础配置"),
        "station_data": get_dict_list("地铁站点基础配置"),
        "ext_transport_data": get_dict_list("多网融合外部交通基础信息"),
        "bus_flow_data": get_dict_list("公交客流数据")
    }


def main(data) -> dict:
    import json
    import math
    from datetime import datetime

    def invalid(message):
        return {
            "is_valid": False,
            "parsed_data": {},
            "error_message": message
        }

    # 1. 反序列化JSON。兼容平台传入JSON字符串或已经解析的字典对象。
    try:
        if isinstance(data, str):
            text = data.lstrip("\ufeff").strip()
            if not text:
                return invalid("参数data不能为空")

            parsed_data = json.loads(text)

            # 部分低代码平台可能将JSON再次编码成字符串，这里兼容一次双重编码。
            if isinstance(parsed_data, str):
                parsed_data = json.loads(parsed_data)
        elif isinstance(data, dict):
            parsed_data = data
        else:
            return invalid(
                "参数data必须是JSON字符串或对象，当前类型为%s"
                % type(data).__name__
            )
    except json.JSONDecodeError as exc:
        return invalid(
            "JSON反序列化失败：第%d行第%d列，%s"
            % (exc.lineno, exc.colno, exc.msg)
        )
    except Exception as exc:
        return invalid("JSON反序列化失败：%s" % str(exc))

    if not isinstance(parsed_data, dict):
        return invalid("JSON顶层必须是对象，不能是数组、字符串或其他类型")

    errors = []
    max_errors = 100

    def add_error(message):
        if len(errors) < max_errors:
            errors.append(message)

    def is_number(value):
        # bool是int的子类，必须显式排除。
        return type(value) in (int, float) and math.isfinite(value)

    def validate_value(section, index, field, value, expected_type):
        location = "%s[%d].%s" % (section, index, field)

        if expected_type == "string":
            if not isinstance(value, str):
                add_error("%s应为字符串" % location)
        elif expected_type == "number":
            if not is_number(value):
                add_error("%s应为有效数字" % location)
        elif expected_type == "boolean":
            if type(value) is not bool:
                add_error("%s应为布尔值true或false" % location)

    def validate_date(section, index, field, value):
        if not isinstance(value, str):
            return
        try:
            datetime.strptime(value, "%Y-%m-%d")
        except ValueError:
            add_error(
                "%s[%d].%s格式错误，应为YYYY-MM-DD"
                % (section, index, field)
            )

    def validate_time_range(section, index, field, value):
        if not isinstance(value, str):
            return
        parts = value.split("-")
        if len(parts) != 2:
            add_error(
                "%s[%d].%s格式错误，应为HH:MM:SS-HH:MM:SS"
                % (section, index, field)
            )
            return
        try:
            datetime.strptime(parts[0], "%H:%M:%S")
            datetime.strptime(parts[1], "%H:%M:%S")
        except ValueError:
            add_error(
                "%s[%d].%s格式错误，应为HH:MM:SS-HH:MM:SS"
                % (section, index, field)
            )

    # 2. 定义当前多网融合工作流需要的四类数据及字段类型。
    schemas = {
        "地铁线路基础配置": {
            "线路名称": "string",
            "线路简称": "string",
            "起点站": "string",
            "终点站": "string",
            "运营里程": "number",
            "车站数量": "number",
            "换乘站数量": "number",
            "开通日期": "string",
            "运营状态": "string"
        },
        "地铁站点基础配置": {
            "车站名称": "string",
            "线路名称": "string",
            "车站顺序": "number",
            "上行相邻站": "string",
            "下行相邻站": "string",
            "是否换乘站": "boolean",
            "换乘线路": "string",
            "所在行政区": "string",
            "站点位置": "string",
            "经度": "number",
            "纬度": "number",
            "站点周边客流属性": "string",
            "接驳交通方式": "string",
            "主要接驳点": "string",
            "出入口数量": "number",
            "站点状态": "string"
        },
        "多网融合外部交通基础信息": {
            "交通方式": "string",
            "运营主体": "string",
            "线路或班次号": "string",
            "站点或设施名称": "string",
            "位置": "string",
            "邻近地铁站": "string",
            "接驳距离": "number",
            "运营时间": "string",
            "服务频次": "string",
            "容量或泊位数": "number",
            "调整类型": "string",
            "生效日期": "string",
            "信息来源": "string"
        },
        "公交客流数据": {
            "日期": "string",
            "公交线路号": "string",
            "站点名称": "string",
            "方向": "string",
            "时段": "string",
            "上车人数": "number",
            "下车人数": "number",
            "断面客流": "number",
            "调整前客流": "number",
            "调整后客流": "number",
            "关联调整事项": "string",
            "数据来源": "string"
        }
    }

    # 3. 校验顶层字段、数组类型、空数组、记录类型、字段存在性及字段类型。
    for section, field_schema in schemas.items():
        if section not in parsed_data:
            add_error("缺少顶层字段：%s" % section)
            continue

        records = parsed_data[section]
        if not isinstance(records, list):
            add_error("顶层字段%s应为数组" % section)
            continue

        if not records:
            add_error("顶层字段%s不能为空数组" % section)
            continue

        for index, record in enumerate(records):
            if not isinstance(record, dict):
                add_error("%s[%d]应为对象" % (section, index))
                continue

            for field, expected_type in field_schema.items():
                if field not in record:
                    add_error("%s[%d]缺少字段：%s" % (section, index, field))
                    continue
                validate_value(
                    section,
                    index,
                    field,
                    record[field],
                    expected_type
                )

    # 基础结构不完整时，避免后续关联校验产生无意义的级联错误。
    sections_ready = all(
        isinstance(parsed_data.get(section), list)
        and len(parsed_data.get(section)) > 0
        for section in schemas
    )

    if sections_ready:
        lines = parsed_data["地铁线路基础配置"]
        stations = parsed_data["地铁站点基础配置"]
        external_transports = parsed_data["多网融合外部交通基础信息"]
        bus_flows = parsed_data["公交客流数据"]

        # 4. 校验日期、时间、非负数值以及经纬度范围。
        for index, record in enumerate(lines):
            if not isinstance(record, dict):
                continue
            validate_date(
                "地铁线路基础配置",
                index,
                "开通日期",
                record.get("开通日期")
            )
            for field in ("运营里程", "车站数量", "换乘站数量"):
                value = record.get(field)
                if is_number(value) and value < 0:
                    add_error(
                        "地铁线路基础配置[%d].%s不能小于0"
                        % (index, field)
                    )

        for index, record in enumerate(stations):
            if not isinstance(record, dict):
                continue
            for field in ("车站顺序", "出入口数量"):
                value = record.get(field)
                if is_number(value) and value < 0:
                    add_error(
                        "地铁站点基础配置[%d].%s不能小于0"
                        % (index, field)
                    )

            longitude = record.get("经度")
            latitude = record.get("纬度")
            if is_number(longitude) and not -180 <= longitude <= 180:
                add_error("地铁站点基础配置[%d].经度超出有效范围" % index)
            if is_number(latitude) and not -90 <= latitude <= 90:
                add_error("地铁站点基础配置[%d].纬度超出有效范围" % index)

            is_transfer = record.get("是否换乘站")
            transfer_lines = record.get("换乘线路")
            if is_transfer is True and isinstance(transfer_lines, str):
                if not transfer_lines.strip():
                    add_error(
                        "地铁站点基础配置[%d]为换乘站时，换乘线路不能为空"
                        % index
                    )

        for index, record in enumerate(external_transports):
            if not isinstance(record, dict):
                continue
            validate_date(
                "多网融合外部交通基础信息",
                index,
                "生效日期",
                record.get("生效日期")
            )
            validate_time_range(
                "多网融合外部交通基础信息",
                index,
                "运营时间",
                record.get("运营时间")
            )
            for field in ("接驳距离", "容量或泊位数"):
                value = record.get(field)
                if is_number(value) and value < 0:
                    add_error(
                        "多网融合外部交通基础信息[%d].%s不能小于0"
                        % (index, field)
                    )

        for index, record in enumerate(bus_flows):
            if not isinstance(record, dict):
                continue
            validate_date(
                "公交客流数据",
                index,
                "日期",
                record.get("日期")
            )
            validate_time_range(
                "公交客流数据",
                index,
                "时段",
                record.get("时段")
            )
            for field in (
                "上车人数",
                "下车人数",
                "断面客流",
                "调整前客流",
                "调整后客流"
            ):
                value = record.get(field)
                if is_number(value) and value < 0:
                    add_error(
                        "公交客流数据[%d].%s不能小于0"
                        % (index, field)
                    )

        # 5. 校验线路与站点关联。
        line_names = {
            record.get("线路名称")
            for record in lines
            if isinstance(record, dict)
            and isinstance(record.get("线路名称"), str)
        }

        station_keys = set()
        station_names = set()
        for index, record in enumerate(stations):
            if not isinstance(record, dict):
                continue
            line_name = record.get("线路名称")
            station_name = record.get("车站名称")

            if isinstance(line_name, str) and line_name not in line_names:
                add_error(
                    "地铁站点基础配置[%d].线路名称%s未在地铁线路基础配置中定义"
                    % (index, line_name)
                )

            if isinstance(line_name, str) and isinstance(station_name, str):
                key = (line_name, station_name)
                if key in station_keys:
                    add_error(
                        "地铁站点基础配置存在重复记录：%s-%s"
                        % (line_name, station_name)
                    )
                station_keys.add(key)
                station_names.add(station_name)

        # 6. 校验外部交通记录是否能够关联到本次输入的地铁重点站，并检查重复记录。
        external_keys = set()
        external_bus_keys = set()
        for index, record in enumerate(external_transports):
            if not isinstance(record, dict):
                continue

            metro_station = record.get("邻近地铁站")
            if isinstance(metro_station, str) and metro_station not in station_names:
                add_error(
                    "多网融合外部交通基础信息[%d].邻近地铁站%s未在地铁站点基础配置中定义"
                    % (index, metro_station)
                )

            key = (
                record.get("交通方式"),
                record.get("线路或班次号"),
                record.get("站点或设施名称"),
                metro_station
            )
            if key in external_keys:
                add_error(
                    "多网融合外部交通基础信息存在重复记录：%s/%s/%s/%s"
                    % key
                )
            external_keys.add(key)

            if record.get("交通方式") == "公交":
                external_bus_keys.add(
                    (
                        record.get("线路或班次号"),
                        record.get("站点或设施名称")
                    )
                )

        # 7. 校验公交客流是否有对应的公交基础信息，并检查业务主键重复。
        bus_flow_keys = set()
        for index, record in enumerate(bus_flows):
            if not isinstance(record, dict):
                continue

            external_bus_key = (
                record.get("公交线路号"),
                record.get("站点名称")
            )
            if external_bus_key not in external_bus_keys:
                add_error(
                    "公交客流数据[%d]的线路和站点未在外部公交基础信息中定义：%s/%s"
                    % (
                        index,
                        record.get("公交线路号"),
                        record.get("站点名称")
                    )
                )

            business_key = (
                record.get("日期"),
                record.get("公交线路号"),
                record.get("站点名称"),
                record.get("方向"),
                record.get("时段"),
                record.get("关联调整事项")
            )
            if business_key in bus_flow_keys:
                add_error(
                    "公交客流数据存在重复业务记录：%s/%s/%s/%s/%s/%s"
                    % business_key
                )
            bus_flow_keys.add(business_key)

    if errors:
        suffix = ""
        if len(errors) >= max_errors:
            suffix = "；错误数量较多，仅返回前%d项" % max_errors
        return invalid(
            "参数校验失败，共%d项：%s%s"
            % (len(errors), "；".join(errors), suffix)
        )

    return {
        "is_valid": True,
        "parsed_data": parsed_data,
        "error_message": ""
    }


def main(line_data, station_data, ext_transport_data, bus_flow_data) -> dict:
    def as_dict_list(value):
        if not isinstance(value, list):
            return []
        return [item for item in value if isinstance(item, dict)]

    def as_number(value, default=0):
        if type(value) in (int, float):
            return value
        return default

    def round_number(value, digits=2):
        return round(float(value), digits)

    def percent(part, total):
        if not total:
            return None
        return round(float(part) / float(total) * 100, 1)

    def percent_text(value):
        if value is None:
            return "无法计算"
        return "%.1f%%" % value

    def time_to_seconds(time_text):
        try:
            hour, minute, second = [int(item) for item in time_text.split(":")]
            return hour * 3600 + minute * 60 + second
        except Exception:
            return None

    def parse_time_range(time_range):
        if not isinstance(time_range, str):
            return None, None
        parts = time_range.split("-")
        if len(parts) != 2:
            return None, None

        start_seconds = time_to_seconds(parts[0])
        end_seconds = time_to_seconds(parts[1])
        if start_seconds is None or end_seconds is None:
            return None, None

        # 结束时间小于开始时间时，表示运营跨越午夜。
        if end_seconds < start_seconds:
            end_seconds += 24 * 3600
        return start_seconds, end_seconds

    def classify_period(time_range):
        start_seconds, _ = parse_time_range(time_range)
        if start_seconds is None:
            return "其他时段"

        start_hour = start_seconds / 3600.0
        if 7 <= start_hour < 10:
            return "早高峰"
        if 17 <= start_hour < 20:
            return "晚高峰"
        if start_hour >= 21 or start_hour < 5:
            return "夜间"
        return "其他时段"

    line_data = as_dict_list(line_data)
    station_data = as_dict_list(station_data)
    ext_transport_data = as_dict_list(ext_transport_data)
    bus_flow_data = as_dict_list(bus_flow_data)

    # 1. 线路及重点站指标。
    line_names = []
    mileage_total = 0
    station_total = 0
    transfer_total = 0

    for record in line_data:
        line_name = record.get("线路名称")
        if isinstance(line_name, str) and line_name not in line_names:
            line_names.append(line_name)
        mileage_total += as_number(record.get("运营里程"))
        station_total += as_number(record.get("车站数量"))
        transfer_total += as_number(record.get("换乘站数量"))

    input_transfer_count = sum(
        1 for record in station_data if record.get("是否换乘站") is True
    )

    district_counts = {}
    for record in station_data:
        district = record.get("所在行政区") or "未提供"
        district_counts[district] = district_counts.get(district, 0) + 1

    district_stats = [
        {
            "行政区": district,
            "重点站数量": count
        }
        for district, count in sorted(
            district_counts.items(),
            key=lambda item: (-item[1], item[0])
        )
    ]

    # 2. 外部交通方式数量及占比。
    mode_counts = {}
    for record in ext_transport_data:
        mode = record.get("交通方式") or "未提供"
        mode_counts[mode] = mode_counts.get(mode, 0) + 1

    ext_total = len(ext_transport_data)
    mode_stats = []
    for mode, count in sorted(
        mode_counts.items(),
        key=lambda item: (-item[1], item[0])
    ):
        rate = percent(count, ext_total)
        mode_stats.append({
            "交通方式": mode,
            "设施数量": count,
            "占比数值": rate,
            "占比": percent_text(rate)
        })

    # 3. 按地铁站汇总接驳设施、方式和距离。
    ext_by_station = {}
    for record in ext_transport_data:
        station_name = record.get("邻近地铁站") or "未提供"
        ext_by_station.setdefault(station_name, []).append(record)

    station_conn_stats = []
    ordered_station_names = []
    for record in station_data:
        station_name = record.get("车站名称")
        if isinstance(station_name, str) and station_name not in ordered_station_names:
            ordered_station_names.append(station_name)

    for station_name in ext_by_station:
        if station_name not in ordered_station_names:
            ordered_station_names.append(station_name)

    for station_name in ordered_station_names:
        records = ext_by_station.get(station_name, [])
        modes = []
        distances = []

        for record in records:
            mode = record.get("交通方式")
            if isinstance(mode, str) and mode not in modes:
                modes.append(mode)
            distance = record.get("接驳距离")
            if type(distance) in (int, float):
                distances.append(float(distance))

        if distances:
            avg_distance = round_number(sum(distances) / len(distances), 2)
            min_distance = round_number(min(distances), 2)
            max_distance = round_number(max(distances), 2)
        else:
            avg_distance = None
            min_distance = None
            max_distance = None

        station_conn_stats.append({
            "车站名称": station_name,
            "接驳设施数": len(records),
            "交通方式数": len(modes),
            "交通方式列表": modes,
            "平均接驳距离": avg_distance,
            "最小接驳距离": min_distance,
            "最大接驳距离": max_distance
        })

    # 4. 长距离接驳和较早结束服务对象。
    long_conn_list = []
    early_end_list = []
    early_end_threshold = 22 * 3600 + 30 * 60

    for record in ext_transport_data:
        distance = record.get("接驳距离")
        if type(distance) in (int, float) and distance > 0.5:
            long_conn_list.append({
                "交通方式": record.get("交通方式"),
                "线路或班次号": record.get("线路或班次号"),
                "站点或设施名称": record.get("站点或设施名称"),
                "邻近地铁站": record.get("邻近地铁站"),
                "接驳距离": round_number(distance, 2)
            })

        _, end_seconds = parse_time_range(record.get("运营时间"))
        if end_seconds is not None and end_seconds <= early_end_threshold:
            early_end_list.append({
                "交通方式": record.get("交通方式"),
                "线路或班次号": record.get("线路或班次号"),
                "站点或设施名称": record.get("站点或设施名称"),
                "邻近地铁站": record.get("邻近地铁站"),
                "运营时间": record.get("运营时间")
            })

    # 5. 公交客流逐条指标。
    bus_detail_stats = []
    bus_before_total = 0
    bus_after_total = 0

    for record in bus_flow_data:
        before = as_number(record.get("调整前客流"))
        after = as_number(record.get("调整后客流"))
        increase = after - before
        increase_rate = percent(increase, before)

        bus_before_total += before
        bus_after_total += after

        bus_detail_stats.append({
            "日期": record.get("日期"),
            "公交线路号": record.get("公交线路号"),
            "站点名称": record.get("站点名称"),
            "方向": record.get("方向"),
            "时段": record.get("时段"),
            "时段类型": classify_period(record.get("时段")),
            "上车人数": as_number(record.get("上车人数")),
            "下车人数": as_number(record.get("下车人数")),
            "断面客流": as_number(record.get("断面客流")),
            "调整前客流": before,
            "调整后客流": after,
            "增加人数": increase,
            "提升率数值": increase_rate,
            "提升率": percent_text(increase_rate),
            "关联调整事项": record.get("关联调整事项")
        })

    bus_increase_total = bus_after_total - bus_before_total
    bus_total_rate = percent(bus_increase_total, bus_before_total)

    # 6. 按调整事项汇总，兼容未来同一事项包含多日期、多时段记录。
    adjustment_groups = {}
    for record in bus_detail_stats:
        adjustment = record.get("关联调整事项") or "未提供"
        if adjustment not in adjustment_groups:
            adjustment_groups[adjustment] = {
                "关联调整事项": adjustment,
                "记录数量": 0,
                "调整前客流": 0,
                "调整后客流": 0,
                "增加人数": 0,
                "公交线路": [],
                "站点": [],
                "时段": []
            }

        group = adjustment_groups[adjustment]
        group["记录数量"] += 1
        group["调整前客流"] += record["调整前客流"]
        group["调整后客流"] += record["调整后客流"]

        for source_field, target_field in (
            ("公交线路号", "公交线路"),
            ("站点名称", "站点"),
            ("时段", "时段")
        ):
            value = record.get(source_field)
            if value not in group[target_field]:
                group[target_field].append(value)

    adjustment_stats = []
    for group in adjustment_groups.values():
        group["增加人数"] = group["调整后客流"] - group["调整前客流"]
        rate = percent(group["增加人数"], group["调整前客流"])
        group["提升率数值"] = rate
        group["提升率"] = percent_text(rate)
        adjustment_stats.append(group)

    adjustment_stats.sort(
        key=lambda item: (
            -(
                item["提升率数值"]
                if item["提升率数值"] is not None
                else -999999
            ),
            item["关联调整事项"]
        )
    )

    # 7. 高增长、最大提升率、最大断面客流及分时段汇总。
    high_growth_records = [
        record for record in bus_detail_stats
        if record["提升率数值"] is not None
        and record["提升率数值"] > 20
    ]

    valid_rate_records = [
        record for record in bus_detail_stats
        if record["提升率数值"] is not None
    ]
    max_rate_record = (
        max(valid_rate_records, key=lambda item: item["提升率数值"])
        if valid_rate_records else {}
    )
    max_section_record = (
        max(bus_detail_stats, key=lambda item: item["断面客流"])
        if bus_detail_stats else {}
    )

    period_groups = {}
    for record in bus_detail_stats:
        period_type = record["时段类型"]
        if period_type not in period_groups:
            period_groups[period_type] = {
                "时段类型": period_type,
                "记录数量": 0,
                "调整前客流": 0,
                "调整后客流": 0,
                "增加人数": 0
            }
        group = period_groups[period_type]
        group["记录数量"] += 1
        group["调整前客流"] += record["调整前客流"]
        group["调整后客流"] += record["调整后客流"]

    period_order = {
        "早高峰": 1,
        "晚高峰": 2,
        "夜间": 3,
        "其他时段": 4
    }
    period_stats = []
    for group in period_groups.values():
        group["增加人数"] = group["调整后客流"] - group["调整前客流"]
        rate = percent(group["增加人数"], group["调整前客流"])
        group["提升率数值"] = rate
        group["提升率"] = percent_text(rate)
        period_stats.append(group)

    period_stats.sort(
        key=lambda item: period_order.get(item["时段类型"], 99)
    )

    metrics_data = {
        "线路数量": len(line_data),
        "线路名称列表": line_names,
        "运营里程合计": round_number(mileage_total, 2),
        "全线车站数量": station_total,
        "全线换乘站数量": transfer_total,
        "本次重点站数量": len(station_data),
        "本次重点站中的换乘站数量": input_transfer_count,
        "行政区统计": district_stats,
        "外部接驳设施总数": ext_total,
        "交通方式统计": mode_stats,
        "重点站接驳统计": station_conn_stats,
        "接驳距离超过0.5公里的设施数": len(long_conn_list),
        "长距离接驳设施": long_conn_list,
        "运营结束时间不晚于22点30分的设施数": len(early_end_list),
        "较早结束服务设施": early_end_list,
        "公交记录数量": len(bus_flow_data),
        "公交调整汇总": {
            "调整前客流合计": bus_before_total,
            "调整后客流合计": bus_after_total,
            "增加人数": bus_increase_total,
            "总体提升率数值": bus_total_rate,
            "总体提升率": percent_text(bus_total_rate)
        },
        "公交调整明细": bus_detail_stats,
        "公交调整事项统计": adjustment_stats,
        "提升率超过20%的记录数": len(high_growth_records),
        "高增长公交记录": high_growth_records,
        "最大提升率记录": max_rate_record,
        "最大断面客流记录": max_section_record,
        "分时段统计": period_stats
    }

    return {
        "metrics_data": metrics_data
    }
